$css = @'

/* Haanel-first conversion story */
.haanelHero{grid-template-columns:minmax(360px,1fr) minmax(420px,1.08fr);min-height:calc(100vh - 80px)}.haanelHero .heroCopy{max-width:760px}.haanelHero h1{display:grid;gap:.35rem;font-size:clamp(3rem,5.6vw,6.6rem);line-height:.92}.haanelHero h1 span{display:block}.haanelHero h1 em{display:block;font-size:.72em;line-height:1.02}.dualPortraits{display:grid;grid-template-columns:1fr 1fr;gap:1rem;align-items:end}.authorityPortrait{position:relative;margin:0;background:#071525;border:1px solid rgba(190,139,61,.55);box-shadow:0 25px 70px rgba(14,24,34,.22);overflow:hidden}.authorityPortrait img{display:block;width:100%;aspect-ratio:4/5;object-fit:cover}.haanelAuthority img{object-position:5% 50%;filter:sepia(.18) contrast(1.04)}.tariqAuthority{transform:translateY(2rem)}.authorityPortrait figcaption{display:grid;gap:.15rem;padding:1rem 1.1rem;background:#071525;color:#fff}.authorityPortrait figcaption span{font-size:.65rem;letter-spacing:.17em;color:#d2a858}.authorityPortrait figcaption strong{font-family:Georgia,serif;font-size:1.1rem}.authorityPortrait figcaption small{font-size:.7rem;color:#aeb8c2}.weeklyProgression{background:#f5f0e7}.progressionGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.2rem;margin:2.5rem 0}.progressionGrid article{padding:2rem;background:#fff;border-top:3px solid #b68032;box-shadow:0 16px 40px rgba(31,42,52,.08)}.progressionGrid span{font-family:Georgia,serif;font-size:2.4rem;color:#c99b58}.progressionGrid h3{font-family:Georgia,serif;font-size:1.7rem;margin:.55rem 0}.progressionGrid p{color:#596570;line-height:1.7}.weeklyProgression blockquote{max-width:980px;margin:2.8rem auto 1rem;padding:2rem clamp(1.5rem,4vw,4rem);font-family:Georgia,serif;font-size:clamp(1.5rem,2.6vw,2.5rem);line-height:1.35;text-align:center;color:#102235;border-left:0}.progressionNote{max-width:760px;margin:0 auto;text-align:center;color:#68737d;line-height:1.7}.meetTariq{display:grid;grid-template-columns:minmax(280px,.78fr) minmax(360px,1.22fr);gap:clamp(2.5rem,6vw,6rem);align-items:center}.meetTariq figure{margin:0}.meetTariq figure img{display:block;width:100%;max-height:720px;object-fit:cover;object-position:center top;box-shadow:0 24px 60px rgba(16,29,42,.18)}.meetTariq h2{font-size:clamp(2.4rem,4.5vw,4.8rem);margin:.45rem 0 1.2rem}.meetTariq>div>p{color:#56616b;line-height:1.75}.coachValue{display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin:1.5rem 0}.coachValue span{padding:.8rem 1rem;background:#f3eee5;border-left:3px solid #b68032;color:#17283a;font-weight:700}
@media(max-width:1080px){.haanelHero{grid-template-columns:1fr}.dualPortraits{max-width:760px;margin:0 auto}.tariqAuthority{transform:none}}
@media(max-width:760px){.dualPortraits{grid-template-columns:1fr 1fr;gap:.55rem}.authorityPortrait figcaption{padding:.75rem}.authorityPortrait figcaption small{display:none}.progressionGrid{grid-template-columns:1fr}.meetTariq{grid-template-columns:1fr}.meetTariq figure{max-width:520px;margin:0 auto}.coachValue{grid-template-columns:1fr}.haanelHero h1{font-size:clamp(2.8rem,13vw,4.5rem)}}
'@

$html = Get-Content -Raw -LiteralPath $htmlPath
$rsc = Get-Content -Raw -LiteralPath $rscPath
$rscLines = $rsc -split "`r?`n"
$oldMetaLine = $rscLines | Where-Object { $_.StartsWith('0:') } | Select-Object -First 1
$oldMainLine = $rscLines | Where-Object { $_.StartsWith('1:') } | Select-Object -First 1
if (-not $oldMetaLine -or -not $oldMainLine) { throw 'Homepage RSC payload lines were not found.' }
if (-not $html.Contains('<section class="hero" id="top">')) { throw 'Existing hero was not found.' }
if (-not $html.Contains('<section class="taster section" id="free-taster">')) { throw 'Taster insertion point was not found.' }

$heroPatternHtml = '<section class="hero" id="top">.*?</section><section class="principle">'
$heroHtmlRegex = [regex]::new($heroPatternHtml)
$html = $heroHtmlRegex.Replace($html, [System.Text.RegularExpressions.MatchEvaluator]{ param($match) $heroHtml + '<section class="principle">' }, 1)
$html = $html.Replace('<section class="taster section" id="free-taster">', $progressionHtml + '<section class="taster section" id="free-taster">')
$html = $html.Replace('<a href="#about-system">The System</a>', '<a href="#about-system">Charles F. Haanel</a>')

$newTitle = "Charles F. Haanel’s Master Key System | Coaching with Tariq Saddique"
$newDescription = "Discover Charles F. Haanel’s progressive 24-part Master Key System with practical coaching, weekly guidance and accountability from Tariq Saddique."
$newSocialTitle = "Charles F. Haanel’s Master Key System with Tariq Saddique"
$html = $html.Replace('<title>Unleash Your Power | 24-Week Master Key Coaching</title>', '<title>' + $newTitle + '</title>')
$html = $html.Replace('<meta name="description" content="A guided 24-week journey with Tariq Saddique through clarity, visualisation, concentration, contemplation and practical inner mastery."/>', '<meta name="description" content="' + $newDescription + '"/>')
$html = $html.Replace('<meta property="og:title" content="Unleash Your Power with Tariq Saddique"/>', '<meta property="og:title" content="' + $newSocialTitle + '"/>')
$html = $html.Replace('<meta property="og:description" content="A guided 24-week Master Key journey through clarity, visualisation, concentration, contemplation and practical action."/>', '<meta property="og:description" content="A progressive 24-part system brought to life through weekly coaching, deliberate practice and accountability."/>')
$html = $html.Replace('<meta name="twitter:title" content="Unleash Your Power with Tariq Saddique"/>', '<meta name="twitter:title" content="' + $newSocialTitle + '"/>')
$html = $html.Replace('<meta name="twitter:description" content="A structured 24-week Master Key coaching journey for practical inner mastery."/>', '<meta name="twitter:description" content="Discover the progressive weekly process behind The Master Key System and experience it with practical coaching."/>')

$heroPatternRsc = '\["\$","section",null,\{"className":"hero","id":"top".*?(?=,\["\$","section",null,\{"className":"principle")'
$heroRegex = [regex]::new($heroPatternRsc)
$newMainLine = $heroRegex.Replace($oldMainLine, [System.Text.RegularExpressions.MatchEvaluator]{ param($match) $heroRsc }, 1)
$newMainLine = $newMainLine.Replace('["$","section",null,{"className":"taster section","id":"free-taster"', $progressionRsc + ',["$","section",null,{"className":"taster section","id":"free-taster"')
$newMainLine = $newMainLine.Replace('"children":"The System"', '"children":"Charles F. Haanel"')

$newMetaLine = $oldMetaLine.Replace('Unleash Your Power | 24-Week Master Key Coaching', $newTitle)
$newMetaLine = $newMetaLine.Replace('A guided 24-week journey with Tariq Saddique through clarity, visualisation, concentration, contemplation and practical inner mastery.', $newDescription)
$newMetaLine = $newMetaLine.Replace('Unleash Your Power with Tariq Saddique', $newSocialTitle)
$newMetaLine = $newMetaLine.Replace('A guided 24-week Master Key journey through clarity, visualisation, concentration, contemplation and practical action.', 'A progressive 24-part system brought to life through weekly coaching, deliberate practice and accountability.')
$newMetaLine = $newMetaLine.Replace('A structured 24-week Master Key coaching journey for practical inner mastery.', 'Discover the progressive weekly process behind The Master Key System and experience it with practical coaching.')

if ($newMainLine -eq $oldMainLine) { throw 'RSC hero transformation did not apply.' }

$rsc = $rsc.Replace($oldMetaLine, $newMetaLine).Replace($oldMainLine, $newMainLine)

function Escape-RscLine([string]$line) {
  return $line.Replace('\', '\\').Replace('"', '\"').Replace('&', '\u0026').Replace('<', '\u003c').Replace('>', '\u003e') + '\n'
}

$oldMetaEscaped = Escape-RscLine $oldMetaLine
$newMetaEscaped = Escape-RscLine $newMetaLine
$oldMainEscaped = Escape-RscLine $oldMainLine
$newMainEscaped = Escape-RscLine $newMainLine
if (-not $html.Contains($oldMetaEscaped)) { throw 'Embedded metadata payload was not found.' }
if (-not $html.Contains($oldMainEscaped)) { throw 'Embedded homepage payload was not found.' }
$html = $html.Replace($oldMetaEscaped, $newMetaEscaped).Replace($oldMainEscaped, $newMainEscaped)

$existingCss = Get-Content -Raw -LiteralPath $cssPath
if ($existingCss.Contains('/* Haanel-first conversion story */')) { throw 'Haanel-first styles have already been added.' }

Set-Content -LiteralPath $htmlPath -Value $html -NoNewline
Set-Content -LiteralPath $rscPath -Value $rsc -NoNewline
Add-Content -LiteralPath $cssPath -Value $css -NoNewline
